mapper.select:
select rs.id, rs.update_time, rs.platform_type, rs.sku_id, rs.sku_no, rs.country, rs.shop_id, rs.platform, rs.replenishment_type, rs.remark, rsd.id as detailId, rsd.sku_type, rsd.fba_usable_qty, rsd.fba_in_transit_qty, rsd.fba_plan_delivery_qty, rsd.overseas_usable_qty, rsd.overseas_in_transit_qty, rsd.overseas_plan_delivery_qty, rsd.local_usable_qty, rsd.local_in_transit_qty, rsd.local_plan_purchase_qty, rsd.total_inventory_qty, rsd.sales_qty as salesQtyJson, rsd.avg_sales_qty as avgSalesQtyJson, rsd.sales_estimate_qty as salesEstimateQtyJson, rsd.avg_sales_estimate_qty as avgSalesEstimateQtyJson, rsd.purchase_approve_days, rsd.purchase_approve_days, rsd.production_days, rsd.supplier_delivery_days, rsd.qc_days, rsd.purchase_cycle_days, rsd.safe_days, rsd.instock_days, rsd.fba_sellable_days, rsd.overseas_sellable_days, rsd.local_sellable_days, rsd.total_sellable_days, rsd.delivery_min_days, rsd.delivery_default_days, rsd.delivery_max_days, rsd.logistics_cycle_days, rsd.logistics_min_cycle_days, rsd.logistics_max_cycle_days, rsd.stock_up_min_days, rsd.stock_up_default_days, rsd.stock_up_max_days, rsd.cfg_fba_in_transit from replenishment_suggestion rs inner join replenishment_suggestion_detail rsd on rs.id = rsd.main_id and rsd.is_deleted = false
${params.sqlMap.default} and rs.is_deleted = FALSE and rs.platform_type = #{params.platformType}
and rsd.sku_type = #{params.skuType}
and exists (select id from replenishment_suggestion_favorite where is_deleted = false and replenishment_suggestion_id = rs.id and user_id = #{userId})
order by rs.replenishment_type asc

select rs.id, rs.update_time, rs.platform_type, rs.sku_id, rs.sku_no, rs.country, rs.shop_id, rs.platform, rs.replenishment_type, rs.remark from replenishment_suggestion rs
rs.is_deleted = false and rs.platform in
#{item}
